diff --git a/src/dsql/Nodes.h b/src/dsql/Nodes.h
index aa6a4a39939..805c159534f 100644
--- a/src/dsql/Nodes.h
+++ b/src/dsql/Nodes.h
@@ -200,20 +200,11 @@ class DdlNode : public Node
 		if (dsqlScratch)
 			dsqlScratch->setTransaction(transaction);

-		try
-		{
-			if (checkPermission(tdbb, transaction))
-				tdbb->tdbb_flags |= TDBB_trusted_ddl;
+		const ULONG flag = checkPermission(tdbb, transaction) ? TDBB_trusted_ddl : 0;

-			execute(tdbb, dsqlScratch, transaction);
-		}
-		catch (...)
-		{
-			tdbb->tdbb_flags &= ~TDBB_trusted_ddl;
-			throw;
-		}
+		Firebird::AutoSetRestoreFlag<ULONG> trustedDdlFlag(&tdbb->tdbb_flags, flag, true);

-		tdbb->tdbb_flags &= ~TDBB_trusted_ddl;
+		execute(tdbb, dsqlScratch, transaction);
 	}

 	virtual DdlNode* dsqlPass(DsqlCompilerScratch* dsqlScratch)
diff --git a/src/jrd/scl.epp b/src/jrd/scl.epp
index e8bf7ac24f5..b1629fe9f0e 100644
--- a/src/jrd/scl.epp
+++ b/src/jrd/scl.epp
@@ -295,7 +295,10 @@ void SCL_check_create_access(thread_db* tdbb, int type)
 	Jrd::Attachment* const attachment = tdbb->getAttachment();

 	// Allow the locksmith any access to database
-	if (attachment->locksmith(tdbb, SystemPrivilege::MODIFY_ANY_OBJECT_IN_DATABASE))
+	// TDBB_trusted_ddl flag may be set in CREATE PACKAGE node. I suppose
+	// if user has CREATE PACKAGE privilege we should not require his to have CREATE FUNCTION as well
+	if ((tdbb->tdbb_flags & TDBB_trusted_ddl) ||
+			attachment->locksmith(tdbb, SystemPrivilege::MODIFY_ANY_OBJECT_IN_DATABASE))
 		return;

 	const SecurityClass::flags_t obj_mask = SCL_get_object_mask(type);
